SELECT course_id, course_name, course_code, teacher_id, dept_id, status, semester, is_public, cover_url, description, version, created_at, updated_at FROM course
deleted_at IS NULL
AND course_name LIKE CONCAT('%',#{query.courseName},'%')
AND status = #{query.status}
AND dept_id = #{query.deptId}
AND semester = #{query.semester}
ORDER BY course_id DESC LIMIT #{offset},#{pageSize}

